import { lazy, Suspense, useEffect, useRef, useState, type ReactNode } from 'react';
const Network = lazy(() => import('./Network'));
import { ArrowDownToLine, ArrowRight, ArrowUp, ArrowUpRight, Archive, BookOpen, Brain, Check, CheckCheck, ChevronDown, ChevronRight, Circle, CircleCheck, Clock3, Code2, Command, Database, Download, File, FileText, Folder, FolderOpen, HardDrive, ImagePlus, Layers3, LayoutDashboard, Loader2, Menu, MessageSquare, MoreHorizontal, Paperclip, Pencil, Pin, Plus, RefreshCw, Search, Send, Settings2, ShieldCheck, Sparkles, Target, Trash2, Upload, WandSparkles, X, Zap } from 'lucide-react';
import type { Connections, Conversation, Doc, Generation, Goal, Page, Source, Workspace } from './types';
import { activity, download, loadWorkspace, makeDoc, now, parseBackup, readData, saveWorkspace, uid } from './lib/storage';
import { api, getConnections, getSources, setAccessToken } from './lib/api';

type Update = (workspace: Workspace) => Workspace;
type Commit = (update: Update, message?: string) => Promise<boolean>;
type Confirm = { title: string; description: string; action: () => Promise<unknown>; label?: string; danger?: boolean };
type Editor = { doc: Doc; fresh: boolean };
const navigation: { id: Page; label: string; icon: typeof Brain; hint?: string }[] = [
  { id: 'overview', label: 'Overview', icon: LayoutDashboard }, { id: 'network', label: 'Network', icon: Layers3 }, { id: 'files', label: 'Files', icon: Folder }, { id: 'skills', label: 'Skills', icon: Zap }, { id: 'goals', label: 'Goals', icon: Target }, { id: 'chat', label: 'Chat', icon: MessageSquare }, { id: 'generate', label: 'Generate', icon: WandSparkles },
];
const labels: Record<Page, string> = { network: 'Network', overview: 'Overview', files: 'Files', skills: 'Skills', goals: 'Goals', chat: 'Chat', generate: 'Generate', settings: 'Settings' };
const providerNames: Record<string, string> = { claude: 'Claude', openai: 'OpenAI', gemini: 'Gemini', kie: 'Kie.ai', fal: 'fal.ai' };
const defaultModels: Record<string, string> = { claude: 'claude-sonnet-5', openai: 'gpt-5.4', gemini: 'gemini-3.5-flash' };
const formatDate = (value: string) => new Date(value).toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
const bytes = (value = 0) => value > 1048576 ? `${(value / 1048576).toFixed(1)} MB` : value > 1024 ? `${Math.round(value / 1024)} KB` : `${value} B`;
const excerpt = (text: string, length = 140) => text.replace(/^#+\s/gm, '').replace(/[\n\r]+/g, ' ').slice(0, length);
const isText = (doc: Doc) => doc.kind !== 'file' || !doc.data || /^(text\/|application\/(json|xml|javascript))/.test(doc.mime || '') || /\.(md|txt|csv|json|yaml|yml|ts|tsx|js|jsx|py|css|html|xml|log)$/i.test(doc.name);
const documentIcon = (doc: Doc) => doc.kind === 'skill' ? Zap : doc.mime?.startsWith('image/') ? ImagePlus : FileText;
function withActivity(w: Workspace, text: string, page: Page): Workspace { return { ...w, activity: [activity(text, page), ...w.activity].slice(0, 100) }; }
function IconButton({ label, children, onClick, className = '', disabled = false }: { label: string; children: ReactNode; onClick: () => void; className?: string; disabled?: boolean }) { return <button type="button" className={`icon-button ${className}`} aria-label={label} title={label} onClick={onClick} disabled={disabled}>{children}</button>; }
function Empty({ icon: Icon = FolderOpen, title, children, action }: { icon?: typeof Brain; title: string; children: ReactNode; action?: ReactNode }) { return <div className="empty-state"><div className="empty-icon"><Icon size={24}/></div><h3>{title}</h3><p>{children}</p>{action}</div>; }
function Modal({ title, children, close, wide = false }: { title: string; children: ReactNode; close: () => void; wide?: boolean }) {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => { const dialog = ref.current!; const previous = document.activeElement as HTMLElement | null; dialog.showModal(); return () => { dialog.close(); previous?.focus(); }; }, []);
  return <dialog ref={ref} className={`modal ${wide ? 'modal-wide' : ''}`} aria-label={title} onCancel={event => { event.preventDefault(); close(); }} onClick={event => { if (event.target === ref.current) close(); }}><header className="modal-header"><h2>{title}</h2><IconButton label="Close dialog" onClick={close}><X size={18}/></IconButton></header>{children}</dialog>;
}
function Markdown({ content }: { content: string }) { return <div className="markdown">{content.split('\n').map((line, i) => line.startsWith('### ') ? <h4 key={i}>{line.slice(4)}</h4> : line.startsWith('## ') ? <h3 key={i}>{line.slice(3)}</h3> : line.startsWith('# ') ? <h2 key={i}>{line.slice(2)}</h2> : /^[-*] /.test(line) ? <p className="markdown-bullet" key={i}>{line.slice(2)}</p> : line.trim() ? <p key={i}>{line}</p> : <div className="paragraph-gap" key={i}/>)}</div>; }
function PageHeading({ eyebrow, title, description, children }: { eyebrow: string; title: string; description: string; children?: ReactNode }) { return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{children && <div className="heading-actions">{children}</div>}</div>; }

export default function App() {
  const [workspace, setWorkspace] = useState<Workspace | null>(null);
  const current = useRef<Workspace | null>(null); const queue = useRef(Promise.resolve());
  const [loadError, setLoadError] = useState(''); const [saving, setSaving] = useState(0);
  const [page, setPage] = useState<Page>(() => { const value = location.hash.slice(1); return value in labels ? value as Page : 'overview'; });
  const [menuOpen, setMenuOpen] = useState(false); const [toast, setToast] = useState<{ text: string; error: boolean } | null>(null);
  const [connections, setConnections] = useState<Connections | null>(null); const [connectionError, setConnectionError] = useState(''); const [checking, setChecking] = useState(false);
  const [editor, setEditor] = useState<Editor | null>(null); const [preview, setPreview] = useState<Doc | null>(null); const [confirm, setConfirm] = useState<Confirm | null>(null);
  const [searchOpen, setSearchOpen] = useState(false); const [search, setSearch] = useState('');
  const [sourcesOpen, setSourcesOpen] = useState<'file' | 'skill' | null>(null); const [attached, setAttached] = useState<string[]>([]); const [activeChat, setActiveChat] = useState<string | null>(null);
  const importRef = useRef<HTMLInputElement>(null);
  const notify = (text: string, error = false) => setToast({ text, error });
  const commit: Commit = (update, message) => new Promise(resolve => {
    setSaving(count => count + 1);
    queue.current = queue.current.then(async () => { try { if (!current.current) throw new Error('Workspace is still loading.'); const next = update(current.current); await saveWorkspace(next); current.current = next; setWorkspace(next); if (message) notify(message); resolve(true); } catch (error) { notify(`Could not save: ${error instanceof Error ? error.message : 'Storage unavailable'}`, true); resolve(false); } finally { setSaving(count => count - 1); } });
  });
  async function connect() { setChecking(true); setConnectionError(''); try { setConnections(await getConnections()); } catch (error) { setConnections(null); setConnectionError(error instanceof Error ? error.message : 'Connection unavailable'); } finally { setChecking(false); } }
  async function load() { setLoadError(''); try { const data = await loadWorkspace(); current.current = data; setWorkspace(data); } catch (error) { setLoadError(error instanceof Error ? error.message : 'Could not open browser storage'); } }
  useEffect(() => { void load(); void connect(); }, []);
  useEffect(() => { if (!toast) return; const timeout = setTimeout(() => setToast(null), toast.error ? 10000 : 4500); return () => clearTimeout(timeout); }, [toast]);
  useEffect(() => { const onHash = () => { const value = location.hash.slice(1); if (value in labels) setPage(value as Page); }; const onKey = (event: KeyboardEvent) => { if ((event.metaKey || event.ctrlKey) && event.key === 'k') { event.preventDefault(); setSearchOpen(value => !value); } }; window.addEventListener('hashchange', onHash); window.addEventListener('keydown', onKey); return () => { window.removeEventListener('hashchange', onHash); window.removeEventListener('keydown', onKey); }; }, []);
  function navigate(next: Page) { setPage(next); location.hash = next; setMenuOpen(false); }
  function newDoc(kind: Doc['kind'] = 'note') { setEditor({ doc: makeDoc('', '', kind), fresh: true }); }
  async function saveDoc(doc: Doc, fresh: boolean) { const next = { ...doc, updated: now() }; const ok = await commit(w => withActivity({ ...w, docs: fresh ? [next, ...w.docs] : w.docs.map(item => item.id === doc.id ? next : item) }, `${fresh ? 'Created' : 'Updated'} ${doc.name}`, doc.kind === 'skill' ? 'skills' : 'files'), fresh ? 'Added to your workspace' : 'Changes saved'); if (ok) { setEditor(null); if (preview?.id === doc.id) setPreview(next); } return ok; }
  async function importFiles(files: FileList | null) { if (!files?.length) return; try { const docs = await Promise.all(Array.from(files).map(async file => { if (file.size > 20 * 1024 * 1024) throw new Error(`${file.name} exceeds the 20 MB file limit.`); const doc = { ...makeDoc(file.name, '', 'file'), mime: file.type || 'application/octet-stream', size: file.size, data: await readData(file) }; if (isText(doc)) doc.content = await file.text(); return doc; })); await commit(w => withActivity({ ...w, docs: [...docs, ...w.docs] }, `Imported ${docs.length} ${docs.length === 1 ? 'file' : 'files'}`, 'files'), `${docs.length} ${docs.length === 1 ? 'file' : 'files'} imported`); } catch (error) { notify(error instanceof Error ? error.message : 'Import failed', true); } if (importRef.current) importRef.current.value = ''; }
  const pinDoc = (doc: Doc) => { void commit(w => ({ ...w, docs: w.docs.map(item => item.id === doc.id ? { ...item, pinned: !item.pinned, updated: now() } : item) }), doc.pinned ? 'Unpinned from overview' : 'Pinned to overview'); if (preview?.id === doc.id) setPreview({ ...doc, pinned: !doc.pinned }); };
  const deleteDoc = (doc: Doc) => setConfirm({ title: `Delete “${doc.name}”?`, description: 'This removes the saved copy and its file bytes from this browser. Your original source file is unaffected. Export a backup first if you need to recover it.', action: async () => { const ok = await commit(w => withActivity({ ...w, docs: w.docs.filter(item => item.id !== doc.id), relations: (w.relations || []).filter(e => e.source !== 'doc:' + doc.id && e.target !== 'doc:' + doc.id) }, `Deleted ${doc.name}`, 'files'), 'Removed from your workspace'); if (ok) { setPreview(null); setAttached(ids => ids.filter(id => id !== doc.id)); } }, danger: true, label: 'Delete permanently' });
  const attachDoc = (doc: Doc) => { setAttached(ids => ids.includes(doc.id) ? ids : [...ids, doc.id]); setPreview(null); navigate('chat'); notify(`${doc.name} attached to Chat`); };
  const exportDoc = (doc: Doc) => download(doc.kind === 'note' || doc.kind === 'skill' ? `${doc.name.replace(/\.md$/, '')}.md` : doc.name, doc.data || new Blob([doc.content], { type: doc.mime || 'text/markdown' }));
  if (!workspace) return <div className="boot-screen"><div className="brand-icon"><Brain size={27}/></div><h1>Second Brain</h1>{loadError ? <><p className="error-text">{loadError}</p><button className="button" onClick={() => void load()}>Retry opening workspace</button></> : <><Loader2 className="spin" size={20}/><p>Opening your workspace…</p></>}</div>;
  const activeGoals = workspace.goals.filter(goal => !goal.archived); const files = workspace.docs.filter(doc => doc.kind !== 'skill'); const skills = workspace.docs.filter(doc => doc.kind === 'skill');
  const searchText = search.trim().toLowerCase();
  return <div className="app-shell">
    <a className="skip-link" href="#main-content">Skip to content</a>
    {menuOpen && <button aria-label="Close navigation" className="sidebar-scrim" onClick={() => setMenuOpen(false)}/>}
    <aside className={`sidebar ${menuOpen ? 'sidebar-open' : ''}`} aria-label="Workspace navigation">
      <button className="brand" onClick={() => navigate('overview')}><span className="brand-icon"><Brain size={22}/></span><span><strong>Second Brain<span className="brand-dot">.</span></strong><small>YOUR PERSONAL WORKSPACE</small></span></button>
      <button className="workspace-switch" onClick={() => navigate('settings')}><span className="workspace-avatar">P</span><span><strong>Personal workspace</strong><small>Just for you</small></span><ChevronDown size={14}/></button>
      <div className="nav-label">WORKSPACE</div>
      <nav>{navigation.map(({ id, label, icon: Icon }) => <button key={id} className={`nav-item ${page === id ? 'active' : ''}`} aria-current={page === id ? 'page' : undefined} onClick={() => navigate(id)}><Icon size={18}/><span>{label}</span>{id === 'files' && <small>{files.length}</small>}{id === 'skills' && <small>{skills.length}</small>}{id === 'chat' && <span className="nav-ai">AI</span>}</button>)}</nav>
      <div className="sidebar-bottom"><div className="local-card"><span className="local-card-icon"><HardDrive size={16}/></span><strong>A home for your mind.</strong><p>Everything you save lives in this browser, on this device.</p><button onClick={() => navigate('settings')}>Manage your data <ArrowUpRight size={13}/></button></div><button className={`nav-item ${page === 'settings' ? 'active' : ''}`} onClick={() => navigate('settings')} aria-current={page === 'settings' ? 'page' : undefined}><Settings2 size={18}/><span>Settings</span></button><div className="profile"><span className="profile-avatar">Y</span><span><strong>Your space</strong><small>Personal · Local storage</small></span><span className="status-dot"/></div></div>
    </aside>
    <div className="main-shell"><header className="topbar"><div className="breadcrumbs"><IconButton label="Open navigation" className="menu-button" onClick={() => setMenuOpen(true)}><Menu size={20}/></IconButton><span className="breadcrumb-root">Workspace</span><ChevronRight size={13}/><strong>{labels[page]}</strong><span className="local-badge"><span className="status-dot"/>Local</span></div><div className="topbar-actions"><span className="save-status">{saving ? <><Loader2 size={12} className="spin"/> Saving…</> : <><CheckCheck size={13}/> Saved on device</>}</span><button className="search-trigger" onClick={() => setSearchOpen(true)}><Search size={15}/><span>Search workspace</span><kbd>Ctrl K</kbd></button></div></header>
      <main id="main-content" className={`main-content page-${page}`} tabIndex={-1}>
        {page === 'network' && <Suspense fallback={<div className="panel boot-screen"><Loader2 className="spin"/><p>Opening your network…</p></div>}><Network workspace={workspace} commit={commit} openDoc={setPreview}/></Suspense>}
        {page === 'overview' && <Overview workspace={workspace} commit={commit} navigate={navigate} openDoc={setPreview} newDoc={newDoc} activeGoals={activeGoals} connections={connections}/>}
        {(page === 'files' || page === 'skills') && <Library key={page} kind={page === 'skills' ? 'skill' : 'file'} docs={page === 'skills' ? skills : files} newDoc={() => newDoc(page === 'skills' ? 'skill' : 'note')} importFiles={() => importRef.current?.click()} openDoc={setPreview} pinDoc={pinDoc} sources={() => setSourcesOpen(page === 'skills' ? 'skill' : 'file')} connections={connections} connectionError={connectionError}/>}
        {page === 'goals' && <Goals workspace={workspace} commit={commit} confirm={setConfirm}/>}
        {page === 'chat' && <Chat workspace={workspace} commit={commit} connections={connections} attached={attached} setAttached={setAttached} activeId={activeChat} setActiveId={setActiveChat} navigate={navigate} notify={notify} confirm={setConfirm}/>}
        {page === 'generate' && <Generate workspace={workspace} commit={commit} connections={connections} navigate={navigate} notify={notify} confirm={setConfirm}/>}
        {page === 'settings' && <Settings workspace={workspace} commit={commit} connections={connections} error={connectionError} checking={checking} refresh={connect} confirm={setConfirm} notify={notify}/>}
      </main>
      <footer className="app-footer"><span><span className="status-dot"/> A little less scattered. A little more you.</span><span>SECOND BRAIN <span className="footer-version">v1.0</span></span></footer>
    </div>
    <input ref={importRef} type="file" multiple className="sr-only" aria-label="Import files" onChange={event => void importFiles(event.target.files)}/>
    {editor && <EditorModal editor={editor} close={() => setEditor(null)} save={saveDoc}/>}
    {preview && <Modal title={preview.kind === 'skill' ? 'Skill details' : 'File details'} close={() => setPreview(null)} wide><div className="preview-meta"><div className={`doc-symbol ${preview.kind}`} >{(() => { const Icon = documentIcon(preview); return <Icon size={25}/>; })()}</div><div><h2>{preview.name}</h2><p>{preview.kind === 'skill' ? 'Personal skill' : preview.kind === 'note' ? 'Note' : preview.mime || 'File'} · Updated {formatDate(preview.updated)} {preview.size ? `· ${bytes(preview.size)}` : ''}</p></div></div><div className="preview-toolbar"><button className={`button small ${preview.pinned ? 'copper-text' : ''}`} onClick={() => pinDoc(preview)}><Pin size={14}/>{preview.pinned ? 'Unpin' : 'Pin'}</button>{isText(preview) && <button className="button small" onClick={() => { setEditor({ doc: preview, fresh: false }); setPreview(null); }}><Pencil size={14}/>Edit</button>}<button className="button small" onClick={() => exportDoc(preview)}><Download size={14}/>Download</button>{isText(preview) && <button className="button small" onClick={() => attachDoc(preview)}><MessageSquare size={14}/>Use in Chat</button>}<IconButton label="Delete saved copy" onClick={() => deleteDoc(preview)} className="danger-text"><Trash2 size={15}/></IconButton></div><div className="preview-content">{preview.data && preview.mime?.startsWith('image/') ? <img className="file-image" src={preview.data} alt={preview.name}/> : preview.data && preview.mime === 'application/pdf' ? <><iframe title={preview.name} className="pdf-preview" src={preview.data}/><p className="muted">If your browser does not display this PDF, use Download above.</p></> : isText(preview) ? <Markdown content={preview.content || 'This file is empty.'}/> : <Empty icon={File} title="Your original file is safely stored">Download this file to open it in its native application.</Empty>}</div>{preview.tags.length > 0 && <div className="preview-tags">{preview.tags.map(tag => <span className="tag" key={tag}>{tag}</span>)}</div>}{preview.source && <div className="source-path"><Folder size={13}/><span>Copied from {preview.source}</span></div>}</Modal>}
    {confirm && <ConfirmModal value={confirm} close={() => setConfirm(null)}/>}
    {sourcesOpen && <SourcesModal kind={sourcesOpen} close={() => setSourcesOpen(null)} commit={commit} openDoc={setPreview} notify={notify} navigate={navigate}/>}
    {searchOpen && <Modal title="Search your workspace" close={() => { setSearchOpen(false); setSearch(''); }} wide><div className="global-search"><Search size={20}/><input aria-label="Search files, goals and conversations" autoFocus placeholder="Find a note, skill, goal, or conversation…" value={search} onChange={event => setSearch(event.target.value)}/></div><div className="search-results">{!searchText ? <Empty icon={Search} title="Everything, within reach">Search the titles, content, and tags of your saved workspace.</Empty> : <>{workspace.docs.filter(doc => `${doc.name} ${doc.content} ${doc.tags.join(' ')}`.toLowerCase().includes(searchText)).slice(0, 20).map(doc => <button className="search-result" key={doc.id} onClick={() => { setSearchOpen(false); setPreview(doc); }}><FileText size={18}/><span><strong>{doc.name}</strong><small>{doc.kind} · {excerpt(doc.content, 80)}</small></span><ArrowUpRight size={15}/></button>)}{workspace.goals.filter(goal => `${goal.title} ${goal.description}`.toLowerCase().includes(searchText)).map(goal => <button className="search-result" key={goal.id} onClick={() => { setSearchOpen(false); navigate('goals'); }}><Target size={18}/><span><strong>{goal.title}</strong><small>Goal · {goal.category}</small></span><ArrowUpRight size={15}/></button>)}{workspace.conversations.filter(chat => `${chat.title} ${chat.messages.map(message => message.content).join(' ')}`.toLowerCase().includes(searchText)).map(chat => <button className="search-result" key={chat.id} onClick={() => { setSearchOpen(false); setActiveChat(chat.id); navigate('chat'); }}><MessageSquare size={18}/><span><strong>{chat.title}</strong><small>Conversation · {chat.messages.length} messages</small></span><ArrowUpRight size={15}/></button>)}{!workspace.docs.some(doc => `${doc.name} ${doc.content} ${doc.tags.join(' ')}`.toLowerCase().includes(searchText)) && !workspace.goals.some(goal => `${goal.title} ${goal.description}`.toLowerCase().includes(searchText)) && !workspace.conversations.some(chat => `${chat.title} ${chat.messages.map(message => message.content).join(' ')}`.toLowerCase().includes(searchText)) && <Empty icon={Search} title="No matches yet">Try another word or a shorter search.</Empty>}</>}</div></Modal>}
    {toast && <div className={`toast ${toast.error ? 'toast-error' : ''}`} role={toast.error ? 'alert' : 'status'}>{toast.error ? <Circle size={17}/> : <CircleCheck size={17}/>}<span>{toast.text}</span><IconButton label="Dismiss notification" onClick={() => setToast(null)}><X size={15}/></IconButton></div>}
  </div>;
}

function Overview({ workspace, commit, navigate, openDoc, newDoc, activeGoals, connections }: { workspace: Workspace; commit: Commit; navigate: (page: Page) => void; openDoc: (doc: Doc) => void; newDoc: (kind?: Doc['kind']) => void; activeGoals: Goal[]; connections: Connections | null }) {
  const [capture, setCapture] = useState(''); const [busy, setBusy] = useState(false);
  const pinned = workspace.docs.filter(doc => doc.pinned); const focus = activeGoals[0];
  const allMilestones = activeGoals.flatMap(goal => goal.milestones); const complete = allMilestones.filter(item => item.done).length;
  async function saveCapture() { if (!capture.trim() || busy) return; setBusy(true); const text = capture.trim(); const doc = makeDoc(text.split('\n')[0].slice(0, 80), text, 'note', ['Quick capture']); if (await commit(w => withActivity({ ...w, docs: [doc, ...w.docs] }, `Captured ${doc.name}`, 'files'), 'Thought captured')) setCapture(''); setBusy(false); }
  const stats = [ { label: 'Files & notes', value: workspace.docs.filter(doc => doc.kind !== 'skill').length, detail: 'Your growing knowledge', icon: Folder, page: 'files' as Page, style: 'copper' }, { label: 'Personal skills', value: workspace.docs.filter(doc => doc.kind === 'skill').length, detail: 'Tools for better thinking', icon: Zap, page: 'skills' as Page, style: 'violet' }, { label: 'Active goals', value: activeGoals.length, detail: `${complete} of ${allMilestones.length} milestones complete`, icon: Target, page: 'goals' as Page, style: 'green' }, { label: 'Conversations', value: workspace.conversations.length, detail: 'Ideas worth coming back to', icon: MessageSquare, page: 'chat' as Page, style: 'blue' } ];
  return <><div className="overview-date"><span className="eyebrow">YOUR PERSONAL OPERATING SYSTEM</span><span><Clock3 size={13}/>{new Date().toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' })}</span></div><section className="welcome"><div><div className="welcome-kicker"><span className="status-dot"/> A clear space. A fresh start.</div><h1>Make room for<br/><span>what matters.</span></h1><p>Your knowledge, ambitions, and a little intelligence.<br className="desktop-break"/> All connected. All in one place.</p><div className="welcome-actions"><button className="button primary" onClick={() => newDoc()}><Plus size={16}/>Capture a thought</button><button className="text-button" onClick={() => navigate('chat')}>Start a conversation <ArrowUpRight size={16}/></button></div></div><div className="brain-orbit" aria-hidden="true"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><div className="orbit orbit-three"/><div className="orbit-center"><Brain size={47} strokeWidth={1.1}/></div><span className="orbit-node node-one"><FileText size={18}/></span><span className="orbit-node node-two"><Zap size={19}/></span><span className="orbit-node node-three"><Target size={19}/></span><span className="orbit-pip pip-one"/><span className="orbit-pip pip-two"/><span className="orbit-caption">CONNECT THE DOTS.</span></div></section>
    <section className="stats-grid" aria-label="Workspace statistics">{stats.map(({ label, value, detail, icon: Icon, page, style }) => <button key={label} className={`stat-card ${style}`} onClick={() => navigate(page)}><div className="stat-top"><span>{label}</span><Icon size={17}/></div><div className="stat-value">{value}<ArrowUpRight size={17}/></div><span className="stat-detail">{detail}</span></button>)}</section>
    <div className="overview-grid"><section className="panel focus-panel"><div className="section-heading"><h2><Target size={17}/>In focus</h2><button className="text-button" onClick={() => navigate('goals')}>All goals <ArrowRight size={14}/></button></div>{focus ? <div className="focus-body"><span className="eyebrow copper-text">{focus.category || 'PERSONAL GOAL'}</span><h3>{focus.title}</h3><p>{focus.description || 'One step at a time. Keep moving toward what matters.'}</p><div className="focus-progress-label"><span>{focus.milestones.filter(item => item.done).length} of {focus.milestones.length} milestones</span><span>{focus.due ? `Due ${formatDate(focus.due + 'T12:00:00')}` : 'No deadline'}</span></div><div className="progress-track"><span style={{ width: `${focus.milestones.length ? focus.milestones.filter(item => item.done).length / focus.milestones.length * 100 : 0}%` }}/></div><button className="button small" onClick={() => navigate('goals')}>Continue your progress <ArrowRight size={14}/></button></div> : <div className="focus-empty"><span className="focus-graphic"><Target size={38} strokeWidth={1}/></span><div><h3>Give your next chapter a direction.</h3><p>Turn something you care about into a goal.<br/>Small milestones. Meaningful progress.</p><button className="button small" onClick={() => navigate('goals')}><Plus size={14}/>Set your first goal</button></div></div>}</section>
      <section className="panel capture-panel"><div className="section-heading"><h2><Pencil size={16}/>Quick capture</h2><span className="subtle-label">GET IT OUT OF YOUR HEAD</span></div><label className="sr-only" htmlFor="quick-capture">Your quick thought</label><textarea id="quick-capture" value={capture} onChange={event => setCapture(event.target.value)} placeholder="An idea, a link, something to remember…" onKeyDown={event => { if ((event.metaKey || event.ctrlKey) && event.key === 'Enter') void saveCapture(); }}/><div className="capture-footer"><span>Saved to Files <kbd>Ctrl ↵</kbd></span><button className="button small primary" disabled={!capture.trim() || busy} onClick={() => void saveCapture()}>{busy ? <Loader2 className="spin" size={14}/> : <Plus size={14}/>}Save note</button></div></section>
    </div>
    <div className="overview-grid lower-grid"><section className="panel pinned-panel"><div className="section-heading"><h2><Pin size={16}/>Close at hand</h2><span className="subtle-label">PINNED</span></div>{pinned.length ? <div className="pinned-list">{pinned.slice(0, 3).map(doc => <button className="pinned-item" key={doc.id} onClick={() => openDoc(doc)}><span className={`doc-symbol ${doc.kind}`}>{doc.kind === 'skill' ? <Zap size={20}/> : <BookOpen size={20}/>}</span><span><strong>{doc.name}</strong><small>{excerpt(doc.content, 100) || 'Open your saved file'}</small><span className="pinned-meta">{doc.tags[0] || doc.kind}<span>·</span>{formatDate(doc.updated)}</span></span><ArrowUpRight size={16}/></button>)}</div> : <div className="inline-empty"><Pin size={23}/><p>Pin a file or skill to keep it within reach.</p><button className="text-button" onClick={() => navigate('files')}>Explore your files <ArrowRight size={14}/></button></div>}</section><section className="panel activity-panel"><div className="section-heading"><h2><Clock3 size={16}/>Recent activity</h2><span className="subtle-label">YOUR WORKSPACE, IN MOTION</span></div><div className="activity-list">{workspace.activity.slice(0, 4).map((item, i) => <button className="activity-item" onClick={() => navigate(item.page)} key={item.id}><span className={`activity-marker ${i === 0 ? 'latest' : ''}`}/><span><strong>{item.text}</strong><small>{formatDate(item.created)} · {new Date(item.created).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' })}</small></span></button>)}</div>{workspace.activity.length < 2 && <p className="activity-hint">The things you capture and create will leave a trail here.</p>}</section></div>
    <div className="connection-strip"><span className="connection-strip-icon"><Layers3 size={17}/></span><div><strong>Your existing work belongs here, too.</strong><span>{connections?.local ? 'Your local library is connected. Bring in project files and Claude skills.' : 'Connect your local library to bring in project files and installed Claude skills.'}</span></div><button className="text-button" onClick={() => navigate('files')}>Explore library <ArrowRight size={15}/></button></div>
  </>;
}

function Library({ kind, docs, newDoc, importFiles, openDoc, pinDoc, sources, connections, connectionError }: { kind: 'file' | 'skill'; docs: Doc[]; newDoc: () => void; importFiles: () => void; openDoc: (doc: Doc) => void; pinDoc: (doc: Doc) => void; sources: () => void; connections: Connections | null; connectionError: string }) {
  const [query, setQuery] = useState(''); const [tag, setTag] = useState('all'); const [filter, setFilter] = useState('all'); const [view, setView] = useState<'grid' | 'list'>('list');
  const isSkill = kind === 'skill'; const tags = [...new Set(docs.flatMap(doc => doc.tags))]; const filtered = docs.filter(doc => `${doc.name} ${doc.content} ${doc.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase()) && (tag === 'all' || doc.tags.includes(tag)) && (filter === 'all' || filter === 'pinned' && doc.pinned || doc.kind === filter));
  return <><PageHeading eyebrow={isSkill ? 'YOUR THINKING TOOLKIT' : 'A PLACE FOR EVERYTHING'} title={isSkill ? 'Skills' : 'Files & notes'} description={isSkill ? 'Give your AI the expertise, instructions, and perspective you need.' : 'Collect what you know. Find it when it matters.'}><button className="button" onClick={isSkill ? sources : importFiles}>{isSkill ? <Code2 size={16}/> : <Upload size={16}/>} {isSkill ? 'Browse installed' : 'Import files'}</button><button className="button primary" onClick={newDoc}><Plus size={16}/>{isSkill ? 'New skill' : 'New note'}</button></PageHeading>
    <div className={`source-banner ${connections?.local ? 'connected' : ''}`}><div className="source-banner-icon">{isSkill ? <Code2 size={23}/> : <FolderOpen size={23}/>}</div><div><div className="source-banner-title"><strong>{isSkill ? 'Your Claude skills, one place away.' : 'Bring your existing world with you.'}</strong><span className={`connection-tag ${connections?.local ? 'online' : ''}`}><span className="status-dot"/>{connections?.local ? 'Local library connected' : connectionError ? 'Server unavailable' : 'Local library not connected'}</span></div><p>{isSkill ? 'Browse installed skills, inspect their instructions, and save a personal copy to use in Chat.' : 'Browse your connected project folders. Save a copy here to read, organize, and use as context.'}</p></div><button className="button small" onClick={sources}>Browse {isSkill ? 'skills' : 'library'} <ArrowUpRight size={14}/></button></div>
    <div className="library-toolbar"><div className="tabs" aria-label="File filters"><button className={filter === 'all' ? 'selected' : ''} onClick={() => setFilter('all')}>All {isSkill ? 'skills' : 'files'}<span>{docs.length}</span></button><button className={filter === 'pinned' ? 'selected' : ''} onClick={() => setFilter('pinned')}><Pin size={13}/>Pinned</button>{!isSkill && <button className={filter === 'note' ? 'selected' : ''} onClick={() => setFilter('note')}>Notes</button>}</div><div className="library-tools"><label className="inline-search"><Search size={15}/><input aria-label={`Search ${isSkill ? 'skills' : 'files'}`} placeholder={`Search ${isSkill ? 'skills' : 'files'}…`} value={query} onChange={event => setQuery(event.target.value)}/></label><select aria-label="Filter by tag" value={tag} onChange={event => setTag(event.target.value)}><option value="all">All tags</option>{tags.map(item => <option key={item}>{item}</option>)}</select><IconButton label={view === 'list' ? 'Switch to grid view' : 'Switch to list view'} onClick={() => setView(view === 'list' ? 'grid' : 'list')}><Layers3 size={16}/></IconButton></div></div>
    {filtered.length > 0 ? <div className={view === 'grid' || isSkill ? 'document-grid' : 'document-table'}>{view === 'list' && !isSkill && <div className="document-table-heading"><span>NAME</span><span>TAGS</span><span>UPDATED</span><span/></div>}{filtered.map(doc => { const Icon = documentIcon(doc); return <article className={`document-card ${view === 'list' && !isSkill ? 'document-row' : ''}`} key={doc.id}><button className="document-open" onClick={() => openDoc(doc)}><span className={`doc-symbol ${doc.kind}`}><Icon size={20}/></span><span className="document-name"><strong>{doc.name}</strong><small>{view === 'grid' || isSkill ? excerpt(doc.content, 130) || 'Open saved file' : `${doc.kind === 'note' ? 'Note' : doc.mime?.split('/')[1]?.toUpperCase() || 'File'}${doc.size ? ' · ' + bytes(doc.size) : ''}`}</small></span>{(view === 'grid' || isSkill) && <ArrowUpRight size={16} className="card-arrow"/>}</button><div className="document-tags">{doc.tags.slice(0, 2).map(item => <button className="tag" key={item} onClick={() => setTag(item)}>{item}</button>)}{!doc.tags.length && <span className="muted">—</span>}</div><time className="document-date" dateTime={doc.updated}>{formatDate(doc.updated)}</time><IconButton label={doc.pinned ? `Unpin ${doc.name}` : `Pin ${doc.name}`} onClick={() => pinDoc(doc)} className={`pin-button ${doc.pinned ? 'is-pinned' : ''}`}><Pin size={15}/></IconButton></article>; })}</div> : <div className="panel library-empty"><Empty icon={isSkill ? Zap : FolderOpen} title={query || tag !== 'all' || filter !== 'all' ? 'Nothing matches this view' : isSkill ? 'Build your thinking toolkit.' : 'Make space for your next idea.'}>{query || tag !== 'all' || filter !== 'all' ? 'Try another search or clear your filters.' : isSkill ? 'Import an installed Claude skill or write your own instructions. Attach a skill in Chat when you want to put it to work.' : 'Add notes, documents, images, and references. They will stay together in your personal library.'}</Empty>{!query && tag === 'all' && filter === 'all' && <button className="button primary" onClick={isSkill ? sources : newDoc}><Plus size={16}/>{isSkill ? 'Explore installed skills' : 'Create your first note'}</button>}</div>}
    <div className="library-footer"><span>{filtered.length} {isSkill ? 'skills' : 'items'} in this view</span><span><ShieldCheck size={13}/>Personal copies · Saved on this device</span></div>
  </>;
}

function EditorModal({ editor, close, save }: { editor: Editor; close: () => void; save: (doc: Doc, fresh: boolean) => Promise<boolean> }) {
  const [name, setName] = useState(editor.doc.name); const [content, setContent] = useState(editor.doc.content); const [tags, setTags] = useState(editor.doc.tags.join(', ')); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [discard, setDiscard] = useState(false);
  const dirty = name !== editor.doc.name || content !== editor.doc.content || tags !== editor.doc.tags.join(', ');
  function requestClose() { if (dirty) setDiscard(true); else close(); }
  async function submit(event: React.FormEvent) { event.preventDefault(); if (!name.trim()) { setError('Give this a title before saving.'); return; } setBusy(true); const changedContent = content !== editor.doc.content; await save({ ...editor.doc, name: name.trim(), content, tags: [...new Set(tags.split(',').map(tag => tag.trim()).filter(Boolean))], ...(changedContent && editor.doc.data ? { data: await readData(new Blob([content], { type: editor.doc.mime || 'text/plain' })), size: new Blob([content]).size } : {}) }, editor.fresh); setBusy(false); }
  return <Modal title={`${editor.fresh ? 'New' : 'Edit'} ${editor.doc.kind === 'skill' ? 'skill' : editor.doc.kind === 'note' ? 'note' : 'text file'}`} close={requestClose} wide><form onSubmit={event => void submit(event)} className="editor-form"><label>Title<input autoFocus value={name} onChange={event => setName(event.target.value)} placeholder={editor.doc.kind === 'skill' ? 'e.g. Thoughtful writing partner' : 'Give your idea a name'} required maxLength={200}/></label><label>{editor.doc.kind === 'skill' ? 'Instructions' : 'Content'}<textarea className="editor-textarea" value={content} onChange={event => setContent(event.target.value)} placeholder={editor.doc.kind === 'skill' ? 'Describe the expertise, approach, and instructions the AI should follow…' : 'Start writing. Markdown headings and lists are welcome.'}/></label><label>Tags<span className="field-hint">Separate with commas</span><input value={tags} onChange={event => setTags(event.target.value)} placeholder="Ideas, Personal, Research" maxLength={500}/></label>{error && <p className="error-text" role="alert">{error}</p>}{discard && <div className="inline-confirm"><span>You have unsaved changes.</span><button type="button" className="text-button danger-text" onClick={close}>Discard changes</button><button type="button" className="text-button" onClick={() => setDiscard(false)}>Keep editing</button></div>}<div className="modal-footer"><span className="muted"><HardDrive size={13}/>Saved on this device</span><button type="button" className="button" onClick={requestClose}>Cancel</button><button className="button primary" disabled={busy || !name.trim()}>{busy ? <Loader2 className="spin" size={15}/> : <Check size={15}/>}Save {editor.doc.kind === 'skill' ? 'skill' : 'note'}</button></div></form></Modal>;
}

function ConfirmModal({ value, close }: { value: Confirm; close: () => void }) { const [busy, setBusy] = useState(false); return <Modal title={value.title} close={() => { if (!busy) close(); }}><div className="confirm-body"><div className={`empty-icon ${value.danger ? 'danger-text' : ''}`}>{value.danger ? <Trash2 size={22}/> : <Database size={22}/>}</div><p>{value.description}</p></div><div className="modal-footer"><button className="button" onClick={close} disabled={busy}>Cancel</button><button className={`button ${value.danger ? 'danger' : 'primary'}`} disabled={busy} onClick={async () => { setBusy(true); try { await value.action(); close(); } finally { setBusy(false); } }}>{busy && <Loader2 className="spin" size={15}/>} {value.label || 'Confirm'}</button></div></Modal>; }

function SourcesModal({ kind, close, commit, openDoc, notify, navigate }: { kind: 'file' | 'skill'; close: () => void; commit: Commit; openDoc: (doc: Doc) => void; notify: (text: string, error?: boolean) => void; navigate: (page: Page) => void }) {
  const [sources, setSources] = useState<Source[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [query, setQuery] = useState(''); const [source, setSource] = useState<(Doc & { sourceId: string }) | null>(null); const [opening, setOpening] = useState(''); const [saving, setSaving] = useState(false);
  async function refresh() { setLoading(true); setError(''); try { setSources((await getSources()).sources.filter(item => item.kind === kind)); } catch (error) { setError(error instanceof Error ? error.message : 'Could not read local library'); } finally { setLoading(false); } }
  useEffect(() => { void refresh(); }, [kind]);
  async function inspect(item: Source) { setOpening(item.id); setError(''); try { const data = await api<{ name: string; content: string; mime: string; data?: string; kind: 'file' | 'skill'; path: string; updated: string }>('source', { id: item.id }); setSource({ ...makeDoc(data.name, data.content, data.kind), mime: data.mime, data: data.data, size: item.size, source: data.path, sourceId: item.id }); } catch (error) { setError(error instanceof Error ? error.message : 'Could not read source'); } finally { setOpening(''); } }
  async function saveCopy() { if (!source || saving) return; setSaving(true); const { sourceId: _sourceId, ...doc } = source; const copy = { ...doc, id: uid(), created: now(), updated: now() }; if (await commit(w => withActivity({ ...w, docs: [copy, ...w.docs] }, `Imported ${copy.name} from local library`, kind === 'skill' ? 'skills' : 'files'))) { notify('Personal copy saved. Your source stays unchanged.'); close(); openDoc(copy); } setSaving(false); }
  const filtered = sources.filter(item => `${item.name} ${item.path}`.toLowerCase().includes(query.toLowerCase()));
  return <Modal title={kind === 'skill' ? 'Installed Claude skills' : 'Connected local library'} close={close} wide>{source ? <><div className="source-detail"><button className="text-button" onClick={() => setSource(null)}>← Back to library</button><h2>{source.name}</h2><p className="source-path">{source.source}</p><div className="source-readonly"><ShieldCheck size={14}/>Source preview · Save a personal copy to edit or use in Chat</div>{source.data && source.mime?.startsWith('image/') ? <img src={source.data} alt={source.name} className="file-image"/> : source.data && source.mime === 'application/pdf' ? <iframe src={source.data} title={source.name} className="pdf-preview"/> : source.content ? <Markdown content={source.content}/> : <Empty icon={File} title="Original file ready to import">Save a copy to retain the file bytes in your workspace.</Empty>}</div><div className="modal-footer"><button className="button" onClick={() => setSource(null)}>Back</button><button className="button primary" disabled={saving} onClick={() => void saveCopy()}>{saving ? <Loader2 className="spin" size={15}/> : <Plus size={15}/>}Save personal copy</button></div></> : <><div className="source-intro"><p>Read files from the folders connected to your local server. Saving a copy brings the content into this browser.</p><label className="inline-search"><Search size={16}/><input autoFocus aria-label="Search local library" value={query} onChange={event => setQuery(event.target.value)} placeholder={kind === 'skill' ? 'Search installed skills…' : 'Search connected files…'}/></label></div>{error && <div className="error-banner" role="alert"><p>{error}</p><button className="button small" onClick={() => void refresh()}><RefreshCw size={14}/>Retry</button><button className="text-button" onClick={() => { close(); navigate('settings'); }}>Connection settings <ArrowUpRight size={14}/></button></div>}<div className="source-list">{loading ? <div className="loading-state"><Loader2 size={23} className="spin"/><p>Reading your local library…</p></div> : filtered.length ? filtered.map(item => <button className="source-item" key={item.id} disabled={!!opening} onClick={() => void inspect(item)}><span className={`doc-symbol ${kind}`}>{kind === 'skill' ? <Zap size={19}/> : <FileText size={19}/>}</span><span><strong>{item.name}</strong><small>{item.path}</small></span><span className="source-size">{bytes(item.size)}</span>{opening === item.id ? <Loader2 size={16} className="spin"/> : <ChevronRight size={16}/>}</button>) : !error && <Empty icon={kind === 'skill' ? Code2 : FolderOpen} title={query ? 'No matching sources' : 'No sources found'}>{query ? 'Try a different name or folder.' : 'Configure your local library folders in the server environment, then refresh. Settings includes the setup details.'}</Empty>}</div><div className="modal-footer"><span className="muted">{sources.length} {kind === 'skill' ? 'skills' : 'files'} found</span><button className="button" onClick={() => void refresh()} disabled={loading}><RefreshCw size={14}/>Refresh library</button></div></>}</Modal>;
}

function Goals({ workspace, commit, confirm }: { workspace: Workspace; commit: Commit; confirm: (value: Confirm) => void }) {
  const [showArchived, setShowArchived] = useState(false); const [editing, setEditing] = useState<Goal | null>(null); const [fresh, setFresh] = useState(false);
  const goals = workspace.goals.filter(goal => goal.archived === showArchived); const total = goals.reduce((sum, goal) => sum + goal.milestones.length, 0); const done = goals.reduce((sum, goal) => sum + goal.milestones.filter(item => item.done).length, 0);
  const create = () => { setFresh(true); setEditing({ id: uid(), title: '', description: '', category: 'Personal', due: '', archived: false, milestones: [], created: now() }); };
  function toggle(goal: Goal, milestoneId: string) { void commit(w => ({ ...w, goals: w.goals.map(item => item.id === goal.id ? { ...item, milestones: item.milestones.map(milestone => milestone.id === milestoneId ? { ...milestone, done: !milestone.done } : milestone) } : item) })); }
  function archive(goal: Goal) { void commit(w => withActivity({ ...w, goals: w.goals.map(item => item.id === goal.id ? { ...item, archived: !item.archived } : item) }, `${goal.archived ? 'Restored' : 'Archived'} goal: ${goal.title}`, 'goals'), goal.archived ? 'Goal restored' : 'Goal archived'); }
  return <><PageHeading eyebrow="MOVE WITH INTENTION" title="Goals" description="Give your ambitions a direction. Make progress one milestone at a time."><button className="button primary" onClick={create}><Plus size={16}/>New goal</button></PageHeading><div className="goal-summary"><div><span className="summary-icon"><Target size={23}/></span><span><strong>{workspace.goals.filter(goal => !goal.archived).length}</strong><small>Active goals</small></span></div><div><span className="summary-icon green-text"><CircleCheck size={23}/></span><span><strong>{done}<span className="summary-total"> / {total}</span></strong><small>Milestones completed {showArchived ? 'in archive' : ''}</small></span></div><p>Progress is a practice.<br/><span>Make the next step a small one.</span></p></div><div className="library-toolbar"><div className="tabs"><button className={!showArchived ? 'selected' : ''} onClick={() => setShowArchived(false)}>Active<span>{workspace.goals.filter(goal => !goal.archived).length}</span></button><button className={showArchived ? 'selected' : ''} onClick={() => setShowArchived(true)}><Archive size={14}/>Archived<span>{workspace.goals.filter(goal => goal.archived).length}</span></button></div></div>{goals.length ? <div className="goals-grid">{goals.map(goal => { const count = goal.milestones.filter(item => item.done).length; const progress = goal.milestones.length ? Math.round(count / goal.milestones.length * 100) : 0; const overdue = goal.due && new Date(goal.due + 'T23:59:59') < new Date() && progress < 100; return <article className="goal-card panel" key={goal.id}><div className="goal-card-top"><span className="tag">{goal.category || 'Personal'}</span><div><IconButton label={`Edit ${goal.title}`} onClick={() => { setFresh(false); setEditing(goal); }}><Pencil size={14}/></IconButton><IconButton label={goal.archived ? `Restore ${goal.title}` : `Archive ${goal.title}`} onClick={() => archive(goal)}><Archive size={14}/></IconButton><IconButton label={`Delete ${goal.title}`} onClick={() => confirm({ title: 'Delete this goal?', description: `“${goal.title}” and all its milestones will be permanently removed from this browser.`, danger: true, label: 'Delete goal', action: () => commit(w => withActivity({ ...w, goals: w.goals.filter(item => item.id !== goal.id), relations: (w.relations || []).filter(e => e.source !== 'goal:' + goal.id && e.target !== 'goal:' + goal.id) }, `Deleted goal: ${goal.title}`, 'goals'), 'Goal deleted') })}><Trash2 size={14}/></IconButton></div></div><h2>{goal.title}</h2><p>{goal.description || 'A little progress, every day.'}</p><div className="goal-progress-label"><span>{count} of {goal.milestones.length} milestones</span><strong>{progress}%</strong></div><div className="progress-track"><span style={{ width: `${progress}%` }}/></div><div className="milestone-list">{goal.milestones.length ? goal.milestones.map(item => <label className={`milestone ${item.done ? 'done' : ''}`} key={item.id}><input type="checkbox" checked={item.done} onChange={() => toggle(goal, item.id)}/><span>{item.title}</span></label>) : <button className="text-button" onClick={() => { setFresh(false); setEditing(goal); }}><Plus size={14}/>Break this goal into milestones</button>}</div><div className={`goal-card-footer ${overdue ? 'copper-text' : ''}`}><Clock3 size={13}/>{goal.due ? `${overdue ? 'Overdue · ' : 'Due '}${formatDate(goal.due + 'T12:00:00')}` : 'No deadline set'}{progress === 100 && goal.milestones.length > 0 && <span className="green-text"><CheckCheck size={14}/>All milestones complete</span>}</div></article>; })}</div> : <div className="panel"><Empty icon={Target} title={showArchived ? 'A place for completed chapters.' : 'What do you want to move toward?'} action={!showArchived && <button className="button primary" onClick={create}><Plus size={16}/>Create your first goal</button>}>{showArchived ? 'Archived goals will stay here, along with their milestones.' : 'A project, a habit, a bigger ambition. Name it, add a few milestones, and give yourself a place to start.'}</Empty></div>}{editing && <GoalEditor goal={editing} fresh={fresh} close={() => setEditing(null)} save={async goal => { const ok = await commit(w => withActivity({ ...w, goals: fresh ? [goal, ...w.goals] : w.goals.map(item => item.id === goal.id ? goal : item) }, `${fresh ? 'Created' : 'Updated'} goal: ${goal.title}`, 'goals'), fresh ? 'Goal created' : 'Goal updated'); if (ok) setEditing(null); }}/>}</>;
}

function GoalEditor({ goal, fresh, close, save }: { goal: Goal; fresh: boolean; close: () => void; save: (goal: Goal) => Promise<void> }) { const [value, setValue] = useState(goal); const [milestone, setMilestone] = useState(''); const [busy, setBusy] = useState(false); const [discard, setDiscard] = useState(false); const dirty = JSON.stringify(value) !== JSON.stringify(goal) || !!milestone; function requestClose() { if (dirty) setDiscard(true); else close(); } function add() { if (milestone.trim()) { setValue({ ...value, milestones: [...value.milestones, { id: uid(), title: milestone.trim(), done: false }] }); setMilestone(''); } } return <Modal title={fresh ? 'A new direction' : 'Edit goal'} close={requestClose}><form className="editor-form" onSubmit={async event => { event.preventDefault(); if (!value.title.trim()) return; setBusy(true); const next = { ...value, title: value.title.trim(), milestones: milestone.trim() ? [...value.milestones, { id: uid(), title: milestone.trim(), done: false }] : value.milestones }; await save(next); setBusy(false); }}><label>Goal title<input autoFocus required value={value.title} onChange={event => setValue({ ...value, title: event.target.value })} placeholder="What do you want to achieve?" maxLength={200}/></label><label>Why it matters<textarea value={value.description} onChange={event => setValue({ ...value, description: event.target.value })} placeholder="Give this goal a little context…" rows={3}/></label><div className="form-two-columns"><label>Category<input value={value.category} onChange={event => setValue({ ...value, category: event.target.value })} placeholder="Personal"/></label><label>Target date<input type="date" value={value.due} onChange={event => setValue({ ...value, due: event.target.value })}/></label></div><div className="field-label">Milestones<span className="field-hint">Make progress tangible</span></div><div className="edit-milestones">{value.milestones.map((item, index) => <div key={item.id}><span className="milestone-number">{String(index + 1).padStart(2, '0')}</span><input aria-label={`Milestone ${index + 1}`} required value={item.title} onChange={event => setValue({ ...value, milestones: value.milestones.map(existing => existing.id === item.id ? { ...existing, title: event.target.value } : existing) })}/><IconButton label={`Remove milestone ${index + 1}`} onClick={() => setValue({ ...value, milestones: value.milestones.filter(existing => existing.id !== item.id) })}><X size={15}/></IconButton></div>)}</div><div className="add-milestone"><input aria-label="New milestone" value={milestone} onChange={event => setMilestone(event.target.value)} placeholder="Add a small, actionable step…" onKeyDown={event => { if (event.key === 'Enter') { event.preventDefault(); add(); } }}/><button type="button" className="button" onClick={add} disabled={!milestone.trim()}><Plus size={15}/>Add</button></div>{discard && <div className="inline-confirm"><span>You have unsaved changes.</span><button type="button" className="text-button danger-text" onClick={close}>Discard changes</button><button type="button" className="text-button" onClick={() => setDiscard(false)}>Keep editing</button></div>}<div className="modal-footer"><button type="button" className="button" onClick={requestClose}>Cancel</button><button className="button primary" disabled={busy || !value.title.trim()}>{busy && <Loader2 className="spin" size={15}/>} {fresh ? 'Create goal' : 'Save changes'}</button></div></form></Modal>; }

function Chat({ workspace, commit, connections, attached, setAttached, activeId, setActiveId, navigate, notify, confirm }: { workspace: Workspace; commit: Commit; connections: Connections | null; attached: string[]; setAttached: (ids: string[] | ((ids: string[]) => string[])) => void; activeId: string | null; setActiveId: (id: string | null) => void; navigate: (page: Page) => void; notify: (text: string, error?: boolean) => void; confirm: (value: Confirm) => void }) {
  const [provider, setProvider] = useState('claude'); const [model, setModel] = useState(connections?.models.claude || defaultModels.claude); const [prompt, setPrompt] = useState(''); const [busy, setBusy] = useState(false); const busyRef = useRef(false); const [error, setError] = useState(''); const [contextOpen, setContextOpen] = useState(false); const [contextQuery, setContextQuery] = useState(''); const [historyOpen, setHistoryOpen] = useState(false); const [rename, setRename] = useState<Conversation | null>(null); const end = useRef<HTMLDivElement>(null);
  const conversation = workspace.conversations.find(chat => chat.id === activeId); const attachedDocs = workspace.docs.filter(doc => attached.includes(doc.id)); const connected = !!connections?.providers[provider];
  useEffect(() => { end.current?.scrollIntoView({ behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth', block: 'nearest' }); }, [conversation?.messages.length, busy]);
  function changeProvider(next: string) { setProvider(next); setModel(connections?.models[next] || defaultModels[next]); setError(''); }
  async function send() { if (!prompt.trim() || !model.trim() || busyRef.current) return; busyRef.current = true; setBusy(true); setError(''); const text = prompt.trim(); const id = conversation?.id || uid(); const userMessage = { id: uid(), role: 'user' as const, content: text, created: now(), provider, model }; const messages = [...(conversation?.messages || []), userMessage]; const chat: Conversation = { id, title: conversation?.title || text.slice(0, 65), messages, updated: now() };
    const saved = await commit(w => ({ ...w, conversations: w.conversations.some(item => item.id === id) ? w.conversations.map(item => item.id === id ? chat : item) : [chat, ...w.conversations] }));
    if (!saved) { busyRef.current = false; setBusy(false); return; } setActiveId(id); setPrompt('');
    try { const response = await api<{ text: string }>('chat', { provider, model: model.trim(), messages: messages.map(message => ({ role: message.role, content: message.content })), context: attachedDocs.filter(isText).map(doc => ({ name: doc.name, content: doc.content, kind: doc.kind })) }); if (!response.text) throw new Error('The provider returned an empty response.'); const assistant = { id: uid(), role: 'assistant' as const, content: response.text, created: now(), provider, model }; const stored = await commit(w => withActivity({ ...w, conversations: w.conversations.map(item => item.id === id ? { ...item, messages: [...item.messages, assistant], updated: now() } : item) }, `Conversation with ${providerNames[provider]}: ${chat.title}`, 'chat')); if (!stored) { download(`unsaved-response-${Date.now()}.txt`, new Blob([response.text], { type: 'text/plain' })); setError('The response could not be saved to browser storage. It has been downloaded as a text file.'); } } catch (error) { setError(error instanceof Error ? error.message : 'The provider could not complete this request.'); } finally { setBusy(false); busyRef.current = false; }
  }
  return <><PageHeading eyebrow="A THINKING PARTNER, WITH CONTEXT" title="Chat" description="Bring your knowledge to the conversation."><button className="button" onClick={() => setHistoryOpen(true)}><Clock3 size={16}/>History<span className="button-count">{workspace.conversations.length}</span></button><button className="button primary" disabled={busy} onClick={() => { setActiveId(null); setPrompt(''); setAttached([]); setError(''); }}><Plus size={16}/>New chat</button></PageHeading><div className="chat-workspace panel"><div className="chat-top"><div className="chat-session-title"><MessageSquare size={17}/><strong>{conversation?.title || 'A new conversation'}</strong>{conversation && <IconButton label="Rename conversation" onClick={() => setRename(conversation)}><Pencil size={13}/></IconButton>}</div><span className={`connection-tag ${connected ? 'online' : ''}`}><span className="status-dot"/>{connected ? `${providerNames[provider]} connected` : `${providerNames[provider]} not configured`}</span></div><div className="chat-messages">{!conversation?.messages.length ? <div className="chat-welcome"><div className="chat-spark"><Sparkles size={30} strokeWidth={1.3}/></div><span className="eyebrow">THINK IT THROUGH, TOGETHER</span><h2>Where should we begin?</h2><p>A half-formed idea. A hard question. A plan that needs a plan.<br/>Bring it here, along with a little context.</p><div className="prompt-starters">{[{ icon: Layers3, title: 'Connect the dots', prompt: 'Help me connect the ideas in my attached notes. What patterns or useful connections do you see?' }, { icon: Target, title: 'Make a plan', prompt: 'Help me turn this idea into a clear, practical plan. Ask me a few questions to get started.' }, { icon: Pencil, title: 'Find the words', prompt: 'Help me develop a clear first draft. Ask about the audience, purpose, and tone before we begin.' }].map(({ icon: Icon, title, prompt }) => <button key={title} onClick={() => setPrompt(prompt)}><Icon size={18}/><strong>{title}</strong><ArrowUpRight size={14}/></button>)}</div></div> : conversation.messages.map(message => <div key={message.id} className={`message message-${message.role}`}><div className="message-avatar">{message.role === 'user' ? 'Y' : <Sparkles size={17}/>}</div><div className="message-body"><div className="message-byline"><strong>{message.role === 'user' ? 'You' : providerNames[message.provider || ''] || 'Assistant'}</strong><span>{message.role === 'assistant' ? message.model : new Date(message.created).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' })}</span></div><Markdown content={message.content}/></div></div>)}{busy && <div className="message"><div className="message-avatar"><Sparkles size={17}/></div><div className="thinking-indicator"><Loader2 size={15} className="spin"/>{providerNames[provider]} is thinking…</div></div>}<div ref={end}/></div>{error && <div className="chat-error error-banner" role="alert"><p>{error}</p><span>Your message is saved. No replacement response has been generated.</span></div>}<div className="chat-composer"><div className="attached-context">{attachedDocs.map(doc => <span className="context-chip" key={doc.id}>{doc.kind === 'skill' ? <Zap size={12}/> : <FileText size={12}/>}<span>{doc.name}</span><button aria-label={`Remove ${doc.name} from context`} onClick={() => setAttached(ids => ids.filter(id => id !== doc.id))}><X size={12}/></button></span>)}</div><label className="sr-only" htmlFor="chat-prompt">Message</label><textarea id="chat-prompt" placeholder="What's on your mind?" value={prompt} onChange={event => setPrompt(event.target.value)} onKeyDown={event => { if (event.key === 'Enter' && !event.shiftKey) { event.preventDefault(); if (connected) void send(); } }}/><div className="composer-controls"><div className="composer-left"><button className="button small context-button" onClick={() => setContextOpen(true)}><Paperclip size={14}/>Add context</button><label className="provider-select"><span className="sr-only">Chat provider</span><select value={provider} disabled={busy} onChange={event => changeProvider(event.target.value)}>{['claude', 'openai', 'gemini'].map(item => <option key={item} value={item}>{providerNames[item]}</option>)}</select></label><label className="model-input"><span className="sr-only">Model ID</span><input aria-label="Chat model ID" title="Editable model ID" value={model} disabled={busy} onChange={event => setModel(event.target.value)}/></label></div><button className="send-button" disabled={busy || !prompt.trim() || !model.trim() || !connected} aria-label="Send message" onClick={() => void send()}>{busy ? <Loader2 className="spin" size={18}/> : <ArrowUp size={19}/>}</button></div></div><div className="chat-disclaimer">{connected ? <><ShieldCheck size={12}/>Only the files and skills you attach are sent as context. Provider usage may incur charges.</> : <><span>Connect a provider to start the conversation.</span><button className="text-button" onClick={() => navigate('settings')}>Open settings <ArrowUpRight size={12}/></button></>}</div></div>
    {contextOpen && <Modal title="Give the conversation some context" close={() => setContextOpen(false)}><div className="source-intro"><p>Select saved files or skills. Their text will be sent to your chosen AI provider with your messages.</p><label className="inline-search"><Search size={15}/><input autoFocus aria-label="Search context" value={contextQuery} onChange={event => setContextQuery(event.target.value)} placeholder="Search files and skills…"/></label></div><div className="context-list">{workspace.docs.filter(doc => `${doc.name} ${doc.tags.join(' ')}`.toLowerCase().includes(contextQuery.toLowerCase())).map(doc => <label className={`context-option ${!isText(doc) ? 'unavailable' : ''}`} key={doc.id}><input type="checkbox" disabled={!isText(doc)} checked={attached.includes(doc.id)} onChange={event => setAttached(ids => event.target.checked ? [...ids, doc.id] : ids.filter(id => id !== doc.id))}/><span className={`doc-symbol ${doc.kind}`}>{doc.kind === 'skill' ? <Zap size={17}/> : <FileText size={17}/>}</span><span><strong>{doc.name}</strong><small>{isText(doc) ? `${doc.kind} · ${doc.content.length.toLocaleString()} characters` : 'Binary file · text context unavailable'}</small></span></label>)}</div><div className="modal-footer"><span className="muted">{attachedDocs.length} attached</span><button className="button primary" onClick={() => setContextOpen(false)}>Done <Check size={15}/></button></div></Modal>}
    {historyOpen && <Modal title="Your conversations" close={() => setHistoryOpen(false)}><div className="conversation-history">{workspace.conversations.length ? workspace.conversations.map(chat => <div className="history-item" key={chat.id}><button disabled={busy} onClick={() => { setActiveId(chat.id); setHistoryOpen(false); setError(''); }}><MessageSquare size={17}/><span><strong>{chat.title}</strong><small>{chat.messages.length} messages · {formatDate(chat.updated)}</small></span></button><IconButton label={`Delete ${chat.title}`} disabled={busy} onClick={() => { setHistoryOpen(false); confirm({ title: 'Delete conversation?', description: `“${chat.title}” and all its messages will be removed from this browser.`, danger: true, label: 'Delete conversation', action: async () => { if (await commit(w => ({ ...w, conversations: w.conversations.filter(item => item.id !== chat.id) }), 'Conversation deleted')) { if (activeId === chat.id) setActiveId(null); } } }); }}><Trash2 size={15}/></IconButton></div>) : <Empty icon={MessageSquare} title="Your conversations will live here">Start a conversation to build a history you can return to.</Empty>}</div></Modal>}
    {rename && <Modal title="Rename conversation" close={() => setRename(null)}><form className="editor-form" onSubmit={async event => { event.preventDefault(); if (await commit(w => ({ ...w, conversations: w.conversations.map(chat => chat.id === rename.id ? { ...chat, title: rename.title.trim() } : chat) }), 'Conversation renamed')) setRename(null); }}><label>Conversation name<input autoFocus value={rename.title} onChange={event => setRename({ ...rename, title: event.target.value })} required maxLength={200}/></label><div className="modal-footer"><button type="button" className="button" onClick={() => setRename(null)}>Cancel</button><button className="button primary" disabled={!rename.title.trim()}>Save name</button></div></form></Modal>}
  </>;
}

function Generate({ workspace, commit, connections, navigate, notify, confirm }: { workspace: Workspace; commit: Commit; connections: Connections | null; navigate: (page: Page) => void; notify: (text: string, error?: boolean) => void; confirm: (value: Confirm) => void }) {
  const [provider, setProvider] = useState('gemini'); const [prompt, setPrompt] = useState(''); const [aspect, setAspect] = useState('1:1'); const [busy, setBusy] = useState(false); const busyRef = useRef(false); const [checking, setChecking] = useState<string[]>([]); const [error, setError] = useState(''); const [selected, setSelected] = useState<Generation | null>(null);
  const connected = !!connections?.providers[provider]; const finished = workspace.generations.filter(item => item.status === 'complete');
  const [recovery, setRecovery] = useState<Workspace | null>(null);
  function offerRecovery(data: Workspace) { setRecovery(data); setError('The provider returned a result, but browser storage could not save it. A recovery backup download was requested. Use Download recovery backup below and restore it in Settings. Do not pay for another run.'); download('second-brain-backup-recovery-' + Date.now() + '.json', new Blob([JSON.stringify(data)], {type:'application/json'})); }
  async function generate() { if (!prompt.trim() || busyRef.current) return; busyRef.current = true; setBusy(true); setError(''); const generation: Generation = { id: uid(), prompt: prompt.trim(), provider, model: connections?.models[provider === 'gemini' ? 'geminiImage' : provider] || ({gemini:'gemini-3.1-flash-image',fal:'fal-ai/flux/schnell',kie:'nano-banana-pro'} as Record<string,string>)[provider], aspect, status: 'queued', images: [], created: now() }; if (!await commit(w => ({ ...w, generations: [generation, ...w.generations] }))) { setBusy(false); busyRef.current = false; return; }
    try { const response = await api<{ job?: string; images: string[]; model: string; status: 'queued' | 'complete' }>('generate', { provider, prompt: generation.prompt, aspect }); let recoverable = workspace; const stored = await commit(w => { recoverable = withActivity({ ...w, generations: w.generations.map(item => item.id === generation.id ? { ...item, ...response } : item) }, response.status === 'complete' ? 'Created an image' : 'Started an image generation', 'generate'); return recoverable; }, response.status === 'complete' ? 'Your image is ready' : 'Generation queued. Check its status to retrieve the result.'); if (!stored) offerRecovery(recoverable); else if (response.status === 'complete') setPrompt(''); } catch (error) { const message = error instanceof Error ? error.message : 'Generation request failed'; setError(message); await commit(w => ({ ...w, generations: w.generations.map(item => item.id === generation.id ? { ...item, status: 'failed', error: message } : item) })); } finally { busyRef.current = false; setBusy(false); }
  }
  async function resume(item: Generation) { if (!item.job || checking.includes(item.id)) return; setChecking(ids => [...ids, item.id]); try { const response = await api<{ job?: string; images: string[]; model: string; status: 'queued' | 'complete' }>('generation-status', { provider: item.provider, job: item.job }); let recoverable = workspace; const stored = await commit(w => { recoverable = { ...w, generations: w.generations.map(existing => existing.id === item.id ? { ...existing, ...response } : existing) }; return recoverable; }, response.status === 'complete' ? 'Your image is ready' : 'Still processing. Check again shortly.'); if (!stored) offerRecovery(recoverable); } catch (error) { notify(error instanceof Error ? error.message : 'Could not check generation', true); } finally { setChecking(ids => ids.filter(id => id !== item.id)); } }
  async function saveImage(item: Generation) { const data = item.images[0]; if (!data) return; const mime = /^data:([^;]+);/.exec(data)?.[1] || 'image/png'; const extension = mime === 'image/jpeg' ? 'jpg' : mime.split('/')[1] || 'png'; const doc: Doc = { ...makeDoc(`Generated image ${formatDate(item.created)}.${extension}`, item.prompt, 'file', ['Generated']), data, mime }; await commit(w => withActivity({ ...w, docs: [doc, ...w.docs] }, 'Saved generated image to Files', 'files'), 'Image added to Files'); }
  return <><PageHeading eyebrow="FROM A THOUGHT TO SOMETHING TANGIBLE" title="Generate" description="Make something new. Keep every result close."><span className="generation-count"><ImagePlus size={16}/>{finished.length} {finished.length === 1 ? 'creation' : 'creations'}</span></PageHeading><div className="generate-layout"><section className="panel generation-composer"><div className="section-heading"><h2><WandSparkles size={17}/>Create an image</h2><span className="tag">STUDIO</span></div><label>What do you imagine?<textarea value={prompt} onChange={event => setPrompt(event.target.value)} placeholder="A quiet reading room at dusk. Warm copper light, shelves of well-loved books, a notebook left open…" rows={7}/></label><div className="prompt-guidance"><Sparkles size={13}/>A subject, a mood, a few details. Start there.</div><label>Provider<select value={provider} disabled={busy} onChange={event => { setProvider(event.target.value); setError(''); }}>{['gemini', 'kie', 'fal'].map(item => <option value={item} key={item}>{providerNames[item]}</option>)}</select></label><div className="field-label">Aspect ratio</div><div className="aspect-options">{['1:1', '16:9', '9:16', '4:3'].map(value => <button key={value} aria-pressed={aspect === value} className={aspect === value ? 'selected' : ''} onClick={() => setAspect(value)}><span style={{ aspectRatio: value.replace(':', ' / '), width: value === '9:16' ? 12 : 21 }}/>{value}</button>)}</div><div className="generation-model"><span>OUTPUT</span><strong>1 image per run</strong><span>{connections?.models[provider === 'gemini' ? 'geminiImage' : provider] || 'Connect to see model'}</span></div><button className="button primary generate-button" disabled={busy || !prompt.trim() || !connected} onClick={() => void generate()}>{busy ? <Loader2 className="spin" size={17}/> : <WandSparkles size={17}/>} {busy ? 'Creating your image…' : 'Generate image'}<ArrowUpRight size={16}/></button><p className="generation-cost">{connected ? 'Runs with your provider API key. Provider usage may incur charges.' : <><span>{providerNames[provider]} is not configured.</span> <button className="text-button" onClick={() => navigate('settings')}>Connect in Settings <ArrowUpRight size={12}/></button></>}</p>{error && <div className="error-banner" role="alert">{error}</div>}{recovery && <button className="button" onClick={() => download("second-brain-backup-recovery.json", new Blob([JSON.stringify(recovery)], {type:"application/json"}))}><Download size={15}/>Download recovery backup</button>}</section><section className="generation-gallery"><div className="gallery-heading"><h2>Your creations</h2><span className="muted">Saved in this browser</span></div>{workspace.generations.length ? <div className="image-grid">{workspace.generations.map(item => <article className="generation-card" key={item.id}>{item.status === 'complete' && item.images[0] ? <button className="generation-image-button" onClick={() => setSelected(item)}><img src={item.images[0]} alt={item.prompt} loading="lazy"/><span><ArrowUpRight size={17}/>View creation</span></button> : <div className={`generation-placeholder ${item.status === 'failed' ? 'failed' : ''}`}><span className="empty-icon">{item.status === 'failed' ? <ImagePlus size={24}/> : <Clock3 size={24}/>}</span><h3>{item.status === 'failed' ? 'Generation could not finish' : item.job ? 'A little imagination in progress.' : busy ? 'Sending to your provider…' : 'No job reference was saved'}</h3><p>{item.error || (item.job ? 'Your job is saved. You can return and retrieve the result.' : 'The request may have been interrupted. Check your provider before starting another run.')}</p>{item.job && item.status !== 'failed' && <button className="button small" onClick={() => void resume(item)} disabled={checking.includes(item.id)}>{checking.includes(item.id) ? <Loader2 size={14} className="spin"/> : <RefreshCw size={14}/>}Check status</button>}</div>}<div className="generation-card-info"><p>{item.prompt}</p><div><span>{providerNames[item.provider]} · {item.aspect}</span><IconButton label="Delete generation from workspace" disabled={busy && item.status === 'queued'} onClick={() => confirm({ title: 'Remove this generation?', description: 'This removes the image or saved job from this browser. It does not cancel a running provider job.', danger: true, label: 'Remove generation', action: () => commit(w => ({ ...w, generations: w.generations.filter(existing => existing.id !== item.id) }), 'Generation removed') })}><Trash2 size={14}/></IconButton></div></div></article>)}</div> : <div className="generation-empty"><div className="empty-art" aria-hidden="true"><div className="art-frame frame-back"/><div className="art-frame frame-middle"/><div className="art-frame frame-front"><div className="art-sun"/><div className="art-mountain one"/><div className="art-mountain two"/><Sparkles size={24}/></div><span className="art-twinkle"><Plus size={16}/></span></div><span className="eyebrow">AN OPEN CANVAS</span><h2>Every image starts<br/>with an idea.</h2><p>Describe what you have in mind.<br/>Your creations will find a home here.</p><div className="empty-provider-pills"><span>Gemini</span><span>Kie.ai</span><span>fal.ai</span></div></div>}</section></div>{selected && <Modal title="Your creation" close={() => setSelected(null)} wide><div className="creation-detail"><img src={selected.images[0]} alt={selected.prompt}/><p>{selected.prompt}</p><span className="muted">{providerNames[selected.provider]} · {selected.model} · {selected.aspect} · {formatDate(selected.created)}</span></div><div className="modal-footer"><button className="button" onClick={() => download("second-brain-generation-" + selected.id + ".json", new Blob([JSON.stringify({prompt:selected.prompt,model:selected.model,provider:selected.provider,aspect:selected.aspect,created:selected.created},null,2)],{type:"application/json"}))}><Download size={15}/>Metadata</button><button className="button" onClick={() => void saveImage(selected)}><Folder size={15}/>Save to Files</button><button className="button primary" onClick={() => download(`second-brain-${selected.id}.${selected.images[0].startsWith('data:image/jpeg') ? 'jpg' : 'png'}`, selected.images[0])}><Download size={15}/>Download image</button></div></Modal>}</>;
}

function Settings({ workspace, commit, connections, error, checking, refresh, confirm, notify }: { workspace: Workspace; commit: Commit; connections: Connections | null; error: string; checking: boolean; refresh: () => Promise<void>; confirm: (value: Confirm) => void; notify: (text: string, error?: boolean) => void }) {
  const [token, setToken] = useState(''); const backupRef = useRef<HTMLInputElement>(null); const [importing, setImporting] = useState(false);
  function exportBackup() { download(`second-brain-backup-${new Date().toISOString().slice(0, 10)}.json`, new Blob([JSON.stringify(workspace, null, 2)], { type: 'application/json' })); notify('Backup downloaded, including original file bytes'); }
  async function importBackup(file: File | undefined) { if (!file) return; setImporting(true); try { if (file.size > 260 * 1024 * 1024) throw new Error('This backup exceeds the 260 MB import limit.'); const data = parseBackup(await file.text()); confirm({ title: 'Replace your workspace from this backup?', description: `Validated backup: ${data.docs.length} files and skills, ${data.goals.length} goals, ${data.conversations.length} conversations, and ${data.generations.length} generations. This replaces the current browser workspace. Export your current data first if you want to keep it.`, label: 'Restore backup', action: () => commit(() => data, 'Workspace restored from backup') }); } catch (error) { notify(`Backup was not imported: ${error instanceof Error ? error.message : 'Invalid file'}`, true); } finally { setImporting(false); if (backupRef.current) backupRef.current.value = ''; } }
  return <><PageHeading eyebrow="MAKE YOURSELF AT HOME" title="Settings" description="Your workspace, your connections, your data."><button className="button" onClick={() => void refresh()} disabled={checking}><RefreshCw size={15} className={checking ? 'spin' : ''}/>{checking ? 'Checking…' : 'Refresh connections'}</button></PageHeading><div className="settings-layout"><div className="settings-main"><section className="panel settings-section"><div className="section-heading"><h2><Zap size={17}/>AI connections</h2><span className={`connection-tag ${connections ? 'online' : ''}`}><span className="status-dot"/>{connections ? 'Server connected' : 'Server unavailable'}</span></div><p className="settings-intro">Connect your preferred intelligence. API keys stay on the server and are never saved in this browser.</p>{error && <div className="error-banner" role="alert">{error}</div>}<div className="provider-grid">{['claude', 'openai', 'gemini', 'kie', 'fal'].map((provider, i) => <div className="provider-card" key={provider}><span className={`provider-monogram provider-${provider}`}>{['C', 'O', 'G', 'K', 'f'][i]}</span><div><strong>{providerNames[provider]}</strong><small>{provider === 'gemini' ? 'Chat & image generation' : provider === 'kie' || provider === 'fal' ? 'Image generation' : 'Chat & reasoning'}</small></div><span className={`provider-state ${connections?.providers[provider] ? 'online' : ''}`}>{connections?.providers[provider] ? <><Check size={12}/>Connected</> : 'Not configured'}</span></div>)}</div><details className="setup-details"><summary><Code2 size={15}/>How to connect providers<ChevronDown size={15}/></summary><p>Add the keys you want to use to your server environment, then restart the server and refresh connections. For local development, copy <code>.env.example</code> to <code>.env</code>. For hosting, use your platform’s environment settings.</p><div className="environment-keys"><code>ANTHROPIC_API_KEY</code><code>OPENAI_API_KEY</code><code>GEMINI_API_KEY</code><code>KIE_API_KEY</code><code>FAL_KEY</code></div><p>Chat model IDs are editable in Chat. Image models are configured on the server. Read the project README for setup and supported providers.</p></details></section><section className="panel settings-section"><div className="section-heading"><h2><FolderOpen size={17}/>Local source library</h2><span className={`connection-tag ${connections?.local ? 'online' : ''}`}><span className="status-dot"/>{connections?.local ? 'Connected' : 'Not connected'}</span></div><div className="settings-info-row"><div className="settings-feature-icon"><HardDrive size={26}/></div><div><h3>Bring your existing work into focus.</h3><p>The local server can read configured project folders and installed Claude skills. Browse them from Files or Skills, then save personal copies.</p></div></div><details className="setup-details"><summary><Code2 size={15}/>Local library setup<ChevronDown size={15}/></summary><p>Run this project locally with <code>npm run dev</code>. Configure the source folder variables in <code>.env.example</code> to point to the documents and skills you want to make available. Remote hosting cannot read folders on your computer.</p><p>Source files are read only. Edits to imported copies stay in your browser workspace.</p></details></section><section className="panel settings-section"><div className="section-heading"><h2><Database size={17}/>Your data</h2><span className="tag">LOCAL STORAGE</span></div><p className="settings-intro">Notes, original file bytes, skills, goals, conversations, and images are saved in this browser using IndexedDB. Clearing site data will remove them.</p><div className="data-actions"><div><div><h3>Take your workspace with you.</h3><p>Download a complete JSON backup, including imported files and generated images.</p></div><button className="button" onClick={exportBackup}><Download size={15}/>Export backup</button></div><div><div><h3>Restore a saved workspace.</h3><p>Import a validated Second Brain backup. You will review the contents before replacing your data.</p></div><button className="button" disabled={importing} onClick={() => backupRef.current?.click()}>{importing ? <Loader2 className="spin" size={15}/> : <Upload size={15}/>}Import backup</button></div></div><input ref={backupRef} className="sr-only" aria-label="Import workspace backup" type="file" accept=".json,application/json" onChange={event => void importBackup(event.target.files?.[0])}/></section>{connections?.authRequired && <section className="panel settings-section"><div className="section-heading"><h2><ShieldCheck size={17}/>Server access</h2></div><p className="settings-intro">This server requires an access token. It stays in memory for this tab and is cleared when you reload.</p><form className="token-form" onSubmit={async event => { event.preventDefault(); setAccessToken(token); setToken(''); await refresh(); }}><label>Access token<input type="password" autoComplete="off" value={token} onChange={event => setToken(event.target.value)} placeholder="Enter server access token"/></label><button className="button primary" disabled={!token.trim()}>Connect</button></form></section>}</div><aside className="settings-aside"><div className="privacy-card"><div className="privacy-emblem"><ShieldCheck size={32} strokeWidth={1.3}/></div><span className="eyebrow">PERSONAL BY DESIGN</span><h2>A space that's<br/>only yours.</h2><p>Your workspace lives on this device. Your API keys live on your server. You choose what becomes AI context.</p><div className="privacy-item"><Check size={14}/><span>No account required</span></div><div className="privacy-item"><Check size={14}/><span>Full backup and restore</span></div><div className="privacy-item"><Check size={14}/><span>You choose what to share</span></div><div className="sync-note"><span className="tag">LOOKING AHEAD</span><p>Cross-device sync is a future step. For now, export a backup to move your workspace between browsers or devices.</p></div></div><div className="settings-fact"><Brain size={20}/><div><strong>Second Brain</strong><span>A little less scattered.</span><small>Version 1.0 · Personal workspace</small></div></div></aside></div>{!connections && <section className="panel settings-section fallback-token"><h3>Using a protected server?</h3><p className="muted">If your server uses an access token, enter it here to reconnect.</p><form className="token-form" onSubmit={async event => { event.preventDefault(); setAccessToken(token); setToken(''); await refresh(); }}><label>Access token<input type="password" autoComplete="off" value={token} onChange={event => setToken(event.target.value)} placeholder="Server access token"/></label><button className="button primary" disabled={!token.trim()}>Connect</button></form></section>}</>;
}
